import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { createLocalReviewAdapter } from '../../../packages/review/src/adapters/local/index.ts';
import { parseReviewCommentsFile } from '../../../packages/review/src/report/index.ts';
import { definition } from '../src/prototype.ts';

/*
 * The demo review (public/review-demo.json, generated by a seeded script and
 * imported from the review toolbar to try comments offline) must be a valid
 * comments file for this prototype, import into the real local adapter, and
 * only pin to anchors (`data-py-anchor`) this prototype renders.
 */

const ROOT = resolve(import.meta.dirname, '..');
const raw = JSON.parse(readFileSync(join(ROOT, 'public/review-demo.json'), 'utf8')) as unknown;
const { slug, storage } = definition.manifest;

function sourceFiles(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? sourceFiles(path) : [path];
  });
}
const anchorsInSource = new Set(
  sourceFiles(join(ROOT, 'src')).flatMap((file) =>
    [...readFileSync(file, 'utf8').matchAll(/data-py-anchor="([a-z0-9-]+)"/g)].map((m) => m[1])
  )
);

describe('demo review fixture', () => {
  it('is a valid comments file for this prototype, with fictional example.com reviewers', () => {
    const file = parseReviewCommentsFile(raw, { slug, namespace: storage.namespace });
    const roots = file.comments.filter((c) => c.id === c.threadId);
    expect(roots).toHaveLength(7);
    expect(file.comments.length).toBeGreaterThan(roots.length);
    for (const comment of file.comments) {
      expect(comment.author.name).toMatch(/\([a-z]+@example\.com\)$/);
    }
    expect(roots.some((c) => c.resolvedAt)).toBe(true);
  });

  it('pins only to anchors the prototype renders', () => {
    const file = parseReviewCommentsFile(raw, { slug, namespace: storage.namespace });
    const used = file.comments.flatMap((c) =>
      (c.anchor?.locators ?? []).filter((l) => l.kind === 'py-anchor').map((l) => l.value)
    );
    expect(used.length).toBe(7);
    for (const anchor of used) expect(anchorsInSource.has(anchor), anchor).toBe(true);
  });

  it('imports into the local review adapter (as the toolbar does), once', async () => {
    expect(definition.manifest.build.review).toMatchObject({ enabled: true, adapter: 'local' });
    const adapter = createLocalReviewAdapter({
      namespace: storage.namespace,
      slug,
      clientId: 'test-reviewer-0001',
    });
    try {
      const blob = new Blob([JSON.stringify(raw)], { type: 'application/json' });
      const total = (raw as { comments: unknown[] }).comments.length;
      expect(await adapter.importComments(blob)).toBe(total);
      expect(await adapter.list(slug)).toHaveLength(total);
      // Importing the same file again adds nothing.
      expect(await adapter.importComments(blob)).toBe(0);
    } finally {
      adapter.close();
    }
  });
});
